INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(5100, 0, 51, 0, 0, 0, 'Searing Gorge', 'The Searing Gorge was born in fire. During the War of the Three Hammers, Sorcerer-Thane Thaurissan of the Dark Iron clan called upon powers sleeping beneath the world and summoned Ragnaros the Firelord. Blackrock Mountain erupted, the Dark Iron capital was thrown down in ruin and the land around it was scorched black, leaving the Burning Steppes to the south and this ravaged valley to the north. Today the gorge is a place of ash, lava and ruthless industry. From Shadowforge City beneath the mountain the Dark Iron dwarves came looking for ore, dug the vast excavation called the Cauldron and filled it with slaves, golems and taskmasters. Fire elementals and lava spiders roam its slopes, and the Twilight''s Hammer keeps a camp in the northwestern hills. Watching all of it from the cliffs of Thorium Point are the Thorium Brotherhood, Dark Iron smiths who broke with their own kin. To the northeast, the locked gates of Stonewrought Pass shut the gorge away from Loch Modan.', 'warcraft.wiki.gg/wiki/Searing_Gorge (history: Thaurissan, Ragnaros, eruption, Cauldron, Thorium Brotherhood left the Dark Iron clan, Stonewrought Pass locked pre-Cataclysm); npc_text 1834-1838 (Pebblebitty: gate locked, beasts of the gorge); quest 3452 description (Twilight''s Hammer encampment in the northwest mountains); DB spawns by subzone (zone_areas.py)'),
(5101, 1, 51, 1, 0, 0, 'Thorium Point', 'Thorium Point clings to the cliffs in the north of the gorge, a guarded outpost looking straight down into the Cauldron. It is the stronghold of the Thorium Brotherhood, Dark Iron smiths who left their clan and now keep a close eye on everything their former kin do below. Brotherhood lookouts stand watch over the camp, and a wanted board posts bounties against the Dark Iron crews and the thieves who rob the camp. Gryphon and wind rider handlers both keep their mounts here, for the Brotherhood welcomes Alliance and Horde alike, and travelers of either banner come to trade with the master craftsmen of the Point.', 'warcraft.wiki.gg/wiki/Thorium_Point (overlooks the Cauldron, Thorium Brotherhood base); warcraft.wiki.gg/wiki/Searing_Gorge (Brotherhood watches the Dark Irons closely); gameobject 179827 Wanted/Missing/Lost & Found; quests 7701, 7728, 7729; DB spawns in area 1446: Thorium Brotherhood Lookouts 14622, Lanie Reed 2941, Grisha 3305; npc_text 7121 (Burninate sends agents on to Lokhtos Darkbargainer); warcraft.wiki.gg/wiki/Thorium_Brotherhood (skilled craftsmen, base on cliffs over the Cauldron in the far north)'),
(5102, 1, 51, 2, 0, 0, 'The Cauldron', 'At the heart of the gorge lies the Cauldron, an enormous pit the Dark Iron dwarves carved out of the blackened valley floor in their hunger for ore. Scaffolds and cart lines cling to its walls, and heavy war golems lumber along its ramps. Slave workers toil without rest under the whips of Dark Iron slavers and taskmasters, so broken by the labor and the heat that they turn on anyone who interferes, would-be rescuers included. Four sentry towers guard the rim, and fire and magma elementals drift through the crevices below. Even here there is trade: the cutthroat dealers of the Undermarket have set up shop in the Cauldron under the protection of their Dark Iron partners.', 'warcraft.wiki.gg/wiki/The_Cauldron (excavation, Slave Workers driven mad, attack liberators, elementals); warcraft.wiki.gg/wiki/Searing_Gorge (mining, enslaved captives); quest 3463 description (four sentry towers); quest 3385 description (Undermarket base in the Cauldron, ties with the Dark Irons); DB spawns in area 246: Slave Worker, Dark Iron Slaver, Taskmaster, Steamsmith, Heavy War Golem, Scaffold Cars, Magma and Blazing Elementals'),
(5103, 1, 51, 3, 0, 0, 'The Slag Pit', 'The Slag Pit is the mine beneath the Cauldron, a maze of hot tunnels rich in ore. Its Dark Iron crew answers to Overseer Maltorius, once of the Thorium Brotherhood, and sleeps in quarters deep inside. Pools of lava in the lower tunnels are home to ravenous incendosaurs. In one hidden chamber stands the altar of Suntara, where captured archaeologists from Ironforge, their minds bent by the stones'' power, labor without rest on something called Obsidion. The Dark Irons guard the pit fiercely against anyone who would meddle with their work.', 'warcraft.wiki.gg/wiki/Slag_Pit (underground mine in the Cauldron, hostile Dark Irons, incendosaurs); quests 7701, 7702, 7722, 7727 (Maltorius, sleeping quarters, lava pools); quest 3368 description (excavation team taken to the Cauldron, working on Obsidion); quest 3372 description, gameobject 148498 Altar of Suntara; DB spawns: Incendosaur 9318, Enslaved Archaeologist 8402, Overseer Maltorius 14621, Obsidion 8400'),
(5104, 1, 51, 4, 0, 0, 'Firewatch Ridge', 'The mountains of the northwestern gorge belong to the Twilight''s Hammer. Their encampment on Firewatch Ridge is held by fire guards, geomancers and dark shamans, while idolaters carry the cult''s relics and symbols of Ragnaros, and Highlord Mastrogonde walks among them. The cult keeps a grim warning on the ridge: a cage holding the spirit of a night elf who once served it, put to death as a blasphemer when he turned back to Elune. Greater lava spiders hunt the slopes around the camp, and lava crabs and fire beetles crawl among the rocks.', 'quest 3452 description (Twilight''s Hammer encampment in the northwest mountains, symbols of Ragnaros); quest 3372 description (Twilight''s Hammer guard a relic in the northwest hills); quest 11952 description (Firewatch Ridge bastion of Twilight activity, ice stones, Tidehunter); npc_text 1922 (Zamael caged as a warning); DB spawns in area 1442: Twilight Fire Guard, Geomancer, Dark Shaman, Idolater, Highlord Mastrogonde, Greater Lava Spider; DB spawns in area 1442: Lava Crab, Fire Beetle; warcraft.wiki.gg/wiki/Firewatch_Ridge (checked; Dark Iron description not used)'),
(5105, 1, 51, 5, 0, 0, 'Grimesilt Dig Site', 'The Grimesilt Dig Site was once worked by the dwarves of Ironforge, but the Dark Iron dwarves have since taken it, and their geologists now work the ground under the watch of watchmen and tempered war golems. It was here that Dorius Stonetender stumbled upon the Suntara stones, a find that ended in slavery for his excavation team. Not every dwarf fared so badly. When a crew member named Locheed hid from the geologists in an outhouse, they simply locked the door behind him and kept the key, and from inside he still begs passersby for help, and for some silk cloth.', 'warcraft.wiki.gg/wiki/Grimesilt_Dig_Site (Ironforge dig site taken by Dark Irons, Dorius, Locheed); creature_text 8421 group 2 (Suntara stones found at the Grimesilt Digsite); quest 3368 description; quests 4449 and 4451 (descriptions and reward texts); DB spawns in area 247: Dark Iron Geologist, Watchman, Tempered War Golem, Wooden Outhouse 173265, Dorius 8284'),
(5106, 1, 51, 6, 0, 0, 'Dustfire Valley', 'Dustfire Valley is a windswept cut through the northeastern gorge, running north toward Stonewrought Pass and the road to Loch Modan beyond. The Dark Irons hold it as they hold most of the gorge: their geologists search the valley for ore, guarded by tempered war golems, while glassweb spiders spin among the rocks. With the gates of the pass kept locked, the valley leads nowhere for most travelers.', 'warcraft.wiki.gg/wiki/Dustfire_Valley (windswept, runs north to Stonewrought Pass, gates locked pre-Shattering); warcraft.wiki.gg/wiki/Stonewrought_Pass (pass at the northern end of Dustfire Valley); DB spawns in area 1959: Dark Iron Geologist, Tempered War Golem, Glassweb Spider, Door 150137'),
(5107, 1, 51, 7, 0, 0, 'Stonewrought Pass', 'Stonewrought Pass is a dwarven tunnel joining the Searing Gorge to Loch Modan, the work of Franclorn Forgewright, the architect whose stonewrought method of building also raised the great dam of Loch Modan. For years both ends have been sealed with locked gates. On the Loch Modan side a mountaineer keeps the key and turns nearly every traveler away, so most who reach the gorge come by the long road through the Badlands or down from Blackrock Mountain instead.', 'warcraft.wiki.gg/wiki/Stonewrought_Pass (tunnel to Loch Modan, locked gates, Pebblebitty, designed by Franclorn Forgewright); quest 3801 description (Franclorn responsible for the stonewrought method); npc_text 1833-1838 (Pebblebitty); quests 3181, 3182, 3201; warcraft.wiki.gg/wiki/Searing_Gorge (pass locked for years; gorge reached through Blackrock Spire or the Badlands trail)'),
(5108, 1, 51, 8, 0, 0, 'Tanner Camp', 'In the southeast of the gorge stands Tanner Camp, the lonely tent of Sarah Tanner, a master of elemental leatherworking who teaches the craft to those willing to open their minds to the greater powers of substance. Her choice of home is a dangerous one: glassweb spiders hunt the surrounding rocks, the great spider Rekk''tilac roams nearby, and a long passage behind her tent leads toward the lair of Margol the Rager.', 'warcraft.wiki.gg/wiki/Tanner_Camp (Sarah Tanner, passage behind her tent to Margol); quest 5144 description (Elemental Leatherworking); DB spawns in area 1958: Sarah Tanner 7868, Glassweb Spider, Rekk''tilac 8277'),
(5109, 1, 51, 9, 0, 0, 'The Sea of Cinders', 'South of the Cauldron the gorge opens into the Sea of Cinders, a broad flat waste scorched by fire and scoured by hot wind. Ash and embers still rise from the smoldering ground and hang in the air, and little lives here that is not made of flame or used to it: searing lava spiders, magma elementals and fire beetles. Dark Iron lookouts keep watch over the plain, which stretches to the foot of Blackrock Mountain.', 'warcraft.wiki.gg/wiki/Sea_of_Cinders (flat southern area north of Blackrock Mountain, ash and embers, uninhabitable); DB spawns in area 1444: Searing Lava Spider, Magma Elemental, Fire Beetle, Dark Iron Lookout'),
(5110, 1, 51, 10, 0, 0, 'Blackchar Cave', 'In the southwestern corner of the gorge, close under Blackrock Mountain, lies Blackchar Cave, a mysterious cavern that has been sealed shut. What lies within is unknown. The ground before it is anything but quiet: Anvilrage taskmasters and enforcers from the Dark Iron city patrol nearby, lava spiders and fire beetles creep among the rocks, and the fire lord Overmaster Pyron burns at the approach to the Blackrock quarry.', 'warcraft.wiki.gg/wiki/Blackchar_Cave (sealed, mysterious, southwestern gorge near Blackrock Mountain, face shape on the map); DB spawns in area 1957: Anvilrage Taskmaster 24818, Anvilrage Enforcer 24819, Overmaster Pyron 9026; quest 4262 description (Pyron guards the entrance at the Blackrock Quarry)'),
(5111, 1, 51, 11, 0, 0, 'Blackrock Mountain', 'The southwestern road of the gorge climbs to Blackrock Mountain, the volcano that rose when Thaurissan''s summoning brought Ragnaros into the world. Within it lie Shadowforge City, capital of the Dark Iron dwarves, and above it the fortress of Blackrock Spire, raised by Dark Iron hands under the Firelord''s will. On the gorge side, quarry slaves cut stone under the eyes of Anvilrage taskmasters and enforcers, and a hulking foe known as the Behemoth roams the approach. Deep within, the Firelord himself holds sway.', 'warcraft.wiki.gg/wiki/Searing_Gorge (Blackrock Mountain eruption, Shadowforge City); npc_text 2316-2317 (Franclorn: Thaurissan under Ragnaros built Blackrock Spire); DB spawns in area 1445: Quarry Slave 8917, Anvilrage Taskmaster 24818, Anvilrage Enforcer 24819; The Behemoth 8924 nearby'),
(5112, 2, 51, 1, 0, 0, 'Kalaran Windblade', 'Kalaran Windblade keeps a lonely camp on the slopes between Thorium Point and the Cauldron, with no company but his lumbering squire, Maltrake. He tells of a father slain by the filth of the Cauldron and of Stormwind magistrates who would not even admit this corner of the world exists, and he swears that riches beyond imagining await anyone who helps him take his revenge. When he works his craft he chants in a tongue no one recognizes, and the effort drops him to one knee. His grief is a mask. Behind the face of a wronged man hides a drake of the black dragonflight, loyal to Blackrock.', 'npc_text 1953-1955 (Kalaran''s tale); creature_text 8480 (Kalaran the Deceiver: legion of Blackrock, plan worked); smart_scripts 8479 and 8509 (Kalaran the Deceiver 8480 summoned after Set Them Ablaze!); warcraft.wiki.gg/wiki/Kalaran_Windblade (black drake, false story about his father); creature_text 8479 (chants in an unknown tongue, falls to one knee exhausted)'),
(5113, 2, 51, 2, 0, 0, 'Overseer Oilfist', 'Overseer Oilfist leads the Thorium Brotherhood from Thorium Point. Under his hand the Brotherhood smiths and trades in the shadow of the Dark Iron works below, buying rare materials from far corners of the world when they promise better armor. He does not forgive desertion. When Maltorius left the Brotherhood to command the Dark Iron crew of the Slag Pit, it was by Oilfist''s own order that a bounty was posted for the traitor''s head.', 'warcraft.wiki.gg/wiki/Thorium_Brotherhood (Oilfist leads the Brotherhood); quest 7701 description (by order of Overseer Oilfist); quest 8858 description and reward text (Oilfist buys colossus chitin for armor)'),
(5114, 2, 51, 3, 0, 0, 'Master Smith Burninate', 'Master Smith Burninate is the forge master of Thorium Point, a gruff dwarf who sells a little food and drink on the side. His great worry is fiery flux, the Brotherhood''s prized smithing reagent. When Maltorius deserted, he took the secret recipe with him, and Burninate wants it back from the Slag Pit, and hopes the traitor''s teeth get kicked in along the way. With the plans recovered, he is eager to rebuild the Brotherhood''s dwindling supply, and he is the one who sends trusted friends on to Lokhtos Darkbargainer in Blackrock Depths.', 'npc_text 7115, 7121 (Burninate gossip); quest 7722 description and reward text; quests 7736, 8241, 8242 completion texts (dwindling fiery flux supply)'),
(5115, 2, 51, 4, 0, 0, 'Lookout Captain Lolo Longstriker', 'The captain of the Thorium Point lookouts is, by his own cheerful admission, as blind as a bat and seldom sober. Lolo Longstriker insists that drink keeps his remaining senses sharp, and claims his sense for drink has never been better. It is he who pays the bounty on Overseer Maltorius, and he greets the traitor''s severed head with slurred delight, remarking that the old face looks better without the rest of him attached.', 'npc_text 7094 (Lolo gossip); quest 7701 description and reward text'),
(5116, 2, 51, 5, 0, 0, 'Hansel Heavyhands', 'Hansel Heavyhands is the Brotherhood''s enforcer, the dwarf they call in when Lolo would rather not spill his ale. He would gladly deal out the pain himself, he says, were it not for his swollen fingers, his bunions and a cold he blames on the frigid climate of the Searing Gorge. Instead he hands the work to others: smashing the heavy war golems around the Cauldron, culling the greater lava spiders, and clearing the incendosaurs from the lava pools of the Slag Pit so the Brotherhood can explore below.', 'npc_text 7117 (Hansel gossip); quests 7723, 7724, 7727 (descriptions and reward texts)'),
(5117, 2, 51, 6, 0, 0, 'Overseer Maltorius', 'Maltorius was once an agent of the Thorium Brotherhood. He went over to the Dark Irons and was rewarded with command of the Slag Pit crew in the Cauldron, a promotion the Brotherhood suspects he bought with their secret recipe for fiery flux. He now rules the mine from deep within its tunnels. At Thorium Point his name is spoken with contempt, and a bounty on his head hangs on the camp''s wanted board.', 'quest 7701 description (rogue Thorium Brotherhood agent, newly hired commander of the Slag Pit crew); quest 7722 description (left the clan with the fiery flux recipe); DB spawn: Overseer Maltorius 14621 in the Slag Pit'),
(5118, 2, 51, 7, 1, 0, 'Dorius Stonetender', 'Dorius Stonetender, brother of Curator Thorius of the Hall of Explorers, led an Ironforge excavation at the Grimesilt Dig Site. There he stumbled upon the Suntara stones, and the power of Ragnaros surged through him. The Firelord gave him a purpose and a new name, Lathoric the Black, acolyte of fire. Feigning a mortal wound and a death on the road, he played on his brother''s grief to draw rescuers into the gorge. He means his creation Obsidion to destroy the Blackrock orcs of the Spire and unite the Dark Irons with their brethren in the fiery depths below.', 'quests 3367, 3368, 3566 (descriptions and reward texts); creature_text 8284 (escort), 8421 (Lathoric''s confession); smart_scripts 8417, 8391 (Lathoric spawned on accepting Release Them); warcraft.wiki.gg/wiki/Lathoric_the_Black (Lathoric is Dorius, brother of Thorius)'),
(5119, 2, 51, 8, 0, 0, 'Zamael Lunthistle', 'In a cage on Firewatch Ridge lingers the spirit of Zamael Lunthistle. As a young night elf in Darkshore he fell in with the Twilight''s Hammer and abandoned his faith in Elune, until a vision from the goddess woke him. In repentance he began a prayer etched on a tablet of pure gold, but the cult found it, branded him a blasphemer and put him to death. Bound to the world and caged as a warning to traitors, he asks only that his unfinished prayer be carried to the Temple of the Moon.', 'npc_text 1920-1922 (Zamael''s tale); quests 3377, 3378 (descriptions and reward texts)'),
(5120, 2, 51, 9, 0, 0, 'Margol the Rager', 'Margol the Rager is a monstrous beast that haunts the southeastern corner of the gorge, called the bane of every archaeologist who ever set foot in the Searing Gorge. Mountaineer Pebblebitty, keeper of the gate at Stonewrought Pass, has faced her and lost the head of an axe in her gigantic horn, in an encounter Curator Thorius will only call ''the incident'' and suspects Pebblebitty would rather have finished herself. Pebblebitty names Margol as the test for anyone who wants a key to the pass.', 'quest 3181 description (axe head of Mountaineer Pebblebitty in the horn); quest 3182 reward text (bane of every archaeologist); quest 3201 description (the incident); npc_text 1838 (southeasternmost corner, lady almost as tough as me)'),
(5121, 2, 51, 10, 0, 0, 'Overmaster Pyron', 'Overmaster Pyron is a lord of fire who guards the quarry at the foot of Blackrock Mountain, a foul spirit the Dark Iron dwarves summoned into the world. The mages Jalinda Sprig sent from Morgan''s Vigil came back burned or worse, and the elders heeded by Thunderheart of Kargath felt his presence as a disturbance among the elements. Pyron cannot be ended so easily. As he falls he swears that Lord Incendius will raise him again from the ashes, a sign that he serves a far greater power within the mountain.', 'quest 3906 description (Dark Irons summoned a foul spirit, lord of fire at the quarry); quest 4262 description and reward text; creature_text 9026 (I will be reborn, Incendius shall raise me); quests 3907, 4263'),
(5122, 3, 51, 1, 0, 0, 'Divine Retribution', 'Kalaran Windblade asks for help avenging his father on the Dark Irons of the Cauldron, and his plan is bold: set the four sentry towers ablaze and blind the Dark Iron defenses before an assault. For that he needs a torch of flawless flame, made from the hearts of fire elementals and golem oil, a shaft reforged from the thorium daggers of Cauldron taskmasters and slavers, and a casing drawn from a Twilight''s Hammer symbol of Ragnaros. Once the towers burn, Squire Maltrake calls the sight glorious, and his master casts off his disguise. Kalaran is a black drake, and the fires were meant to open the way for the legion of Blackrock to invade the gorge. Mockingly he lets his helpers live to see the chaos to come, leaving them a chest of trinkets and a molt of his flight that his kin in the Burning Steppes will know how to use, before he takes wing.', 'quests 3441-3463, 3481 (descriptions and reward texts); npc_text 1953-1955; creature_text 8480, 8509 (the reveal); gameobject 149502 Hoard of the Black Dragonflight; quest 4022 (molt shown to Cyrus Therepentous); smart_scripts 8509, 8479 (Kalaran the Deceiver 8480 summoned on turning in 3463)'),
(5123, 3, 51, 2, 1, 0, 'The Suntara Stones', 'At the Grimesilt Dig Site lies Dorius Stonetender, badly wounded and desperate to reach Ironforge. On the run for the gate he is shot down, and the letter he drops finds its way to his brother Thorius: the Dark Irons hold the Suntara stones, their leader Lathoric the Black uses them to enslave the excavation team, and the captives toil in the Cauldron on something called Obsidion. Vowing to honor the dying wish, Thorius sends rescuers into the Slag Pit. There a dying archaeologist begs them to free his comrades by taking a relic from the Twilight''s Hammer in the northwest hills and placing it on the altar of Suntara. It is a trap. The relic was the last stone Lathoric needed, and Lathoric is Dorius himself, alive and mocking, who calls Obsidion to rise. When the head of Lathoric is laid before Thorius, the curator''s grief turns to fury, and to fear of how far the will of Ragnaros reaches.', 'quests 3367, 3368, 3371, 3372, 3566 (descriptions and reward texts); creature_text 8284, 8421; warcraft.wiki.gg/wiki/Lathoric_the_Black'),
(5124, 3, 51, 3, 1, 0, 'The Key to the Gorge', 'Mountaineer Pebblebitty will not open the gate at Stonewrought Pass. The gorge is full of beasts that have killed good dwarves, she says, and if she lets one traveler in she will have to let in everyone. Pressed, she admits there is a back road through the Badlands near Kargath, and offers a key to anyone who returns with proof of heroics, pointing to Margol the Rager in the far southeast of the gorge. Margol''s gigantic horn once carried Pebblebitty''s own broken axe head, but it shatters when pulled free, and without it she calls the horn a fake. Only when Curator Thorius in Ironforge recognizes the horn of the bane of every archaeologist, claims it for his museum and signs a proof of deed does Pebblebitty grudgingly hand over the key, warning that whatever happens next is the bearer''s own fault.', 'npc_text 1833-1839 (Pebblebitty); quests 3181, 3182, 3201 (descriptions and reward texts)'),
(5125, 3, 51, 4, 0, 0, 'The Brotherhood and the Slag Pit', 'The Thorium Brotherhood has a quarrel with the Slag Pit, and it is personal. Overseer Maltorius, one of their own, deserted to take command of the Dark Iron crew there, and the Brotherhood believes he paid for the post with their recipe for fiery flux. Thorium Point answers with every weapon it has. Master Smith Burninate wants the stolen plans back, the wanted board offers a bounty on Maltorius''s head, and Taskmaster Scrange pays to cull the Dark Iron taskmasters and slavers and to recover a spyglass and smithing tuyere stolen from the camp. Evonice Sootsmoker has a subtler idea: steal the crew''s pillows, since sleepless dwarves will go home to the Depths to rest. Hansel Heavyhands, meanwhile, wants golems, lava spiders and incendosaurs cleared so Brotherhood teams can explore the pit. With the plans recovered, the Brotherhood can set about rebuilding its dwindling stock of fiery flux.', 'quests 7701, 7702, 7722, 7723, 7724, 7727, 7728, 7729 (descriptions and reward texts); quests 7736, 8241, 8242'),
(5126, 3, 51, 5, 0, 0, 'The Undermarket', 'Nilith Lokrav, a tailor who prizes the shadow silk of the gorge''s spiders, works in the south of the gorge with Raze, the hulking guardian who smashes on command. First she wants the shadowsilk poachers who slaughter spiders without thought for the future put down. Then she names a greater enemy. The Undermarket, a ring of cutthroat traders who will sell or move anything for a price, has opened a base in the Cauldron under Trade Master Kovic, who keeps close ties with the Dark Iron dwarves. Kovic and his minion Clunk must die. News of the Trade Master''s death is welcome as far away as Gadgetzan, where Vizzklick celebrates the end of years of shady deals and undercut honest merchants.', 'quests 3379, 3385, 3402 (descriptions and reward texts); creature_text 8439, 8441 (Raze and the staff); DB spawns: Nilith Lokrav 8439 and Raze 8441 in the south of the gorge, Kovic 8444 and Clunk 8447 in area 246');
